#include <WiFi.h>
#include <WebServer.h>

// --- Настройки Wi-Fi ---
const char* ssid = "ZTE_a81eb0";
const char* password = "ВАШ_ПАРОЛЬ"; // <-- ВПИШИТЕ СЮДА ПАРОЛЬ ОТ WI-FI

// --- Настройки пина ---
const int ledPin = 2; // D2 на ESP32

// Создаем объект веб-сервера на 80 порту
WebServer server(80);

// Функция для главной страницы
void handleRoot() {
  // Формируем HTML-страницу, которая будет открываться в браузере
    String html = "<!DOCTYPE html><html><head><meta charset='utf-8'>";
      html += "<meta name='viewport' content='width=device-width, initial-scale=1.0'>";
        html += "<title>ESP32 Web Server</title></head><body style='text-align:center; font-family:Arial; margin-top:50px;'>";
          html += "<h1>Управление светодиодом</h1>";
            html += "<p><a href='/on'><button style='padding:15px 30px; font-size:18px; background:#4CAF50; color:white; border:none; border-radius:5px;'>ВКЛЮЧИТЬ</button></a></p>";
              html += "<p><a href='/off'><button style='padding:15px 30px; font-size:18px; background:#f44336; color:white; border:none; border-radius:5px;'>ВЫКЛЮЧИТЬ</button></a></p>";
                html += "</body></html>";
                  server.send(200, "text/html", html);
                  }

                  // Функция для включения светодиода
                  void handleOn() {
                    digitalWrite(ledPin, HIGH);
                      server.sendHeader("Location", "/"); // Возвращаем пользователя на главную
                        server.send(303);
                        }

                        // Функция для выключения светодиода
                        void handleOff() {
                          digitalWrite(ledPin, LOW);
                            server.sendHeader("Location", "/");
                              server.send(303);
                              }

                              void setup() {
                                Serial.begin(115200);
                                  delay(1000);
                                    pinMode(ledPin, OUTPUT);
                                      digitalWrite(ledPin, LOW); // Изначально выключен

                                        Serial.println();
                                          Serial.print("Подключение к Wi-Fi: ");
                                            Serial.println(ssid);

                                              // Подключаемся к Wi-Fi
                                                WiFi.begin(ssid, password);

                                                  // Ждем подключения
                                                    while (WiFi.status() != WL_CONNECTED) {
                                                        delay(500);
                                                            Serial.print(".");
                                                              }

                                                                Serial.println("");
                                                                  Serial.println("Wi-Fi подключен успешно!");

                                                                      // Выводим IP-адрес в логи. По нему вы будете заходить с телефона!
                                                                        Serial.print("IP-адрес: http://");
                                                                          Serial.println(WiFi.localIP());

                                                                            // Привязываем функции к адресам (маршрутам)
                                                                              server.on("/", handleRoot);
                                                                                server.on("/on", handleOn);
                                                                                  server.on("/off", handleOff);

                                                                                    // Запускаем сервер
                                                                                      server.begin();
                                                                                        Serial.println("Веб-сервер запущен.");
                                                                                        }

                                                                                        void loop() {
                                                                                          // Обрабатываем входящие запросы от браузера
                                                                                            server.handleClient();
                                                                                            }
